-- Migration: backfill customer loyalty level from legacy_code.
-- Mapping per codes.csv.

ALTER TABLE customers ADD COLUMN reward_band TEXT;

UPDATE customers SET reward_band = 'gold'   WHERE legacy_code = 'A';
UPDATE customers SET reward_band = 'silver' WHERE legacy_code = 'B';
UPDATE customers SET reward_band = 'bronze' WHERE legacy_code = 'C';
